from lxml import etree
from copy import deepcopy
src='documents/technova-ai-vendor-agreement-draft-2-redline.docx'; out='clean-base.docx'
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'; ns={'w':W}; q=lambda t: f'{{{W}}}{t}'

def accept(root):
    # repeat until no revision containers
    for ins in list(root.xpath('.//w:ins',namespaces=ns)):
        par=ins.getparent(); idx=par.index(ins)
        for ch in list(ins): par.insert(idx, ch); idx+=1
        par.remove(ins)
    for dele in list(root.xpath('.//w:del',namespaces=ns)):
        dele.getparent().remove(dele)
    for node in root.xpath('.//w:delText',namespaces=ns):
        node.tag=q('t')
    return root
with ZipFile(src) as zin:
    files={n:zin.read(n) for n in zin.namelist()}
root=etree.fromstring(files['word/document.xml']); files['word/document.xml']=etree.tostring(accept(root),xml_declaration=True,encoding='UTF-8',standalone='yes')
# Accept revisions in headers/footers/comments if any
for n in list(files):
    if n.startswith('word/') and n.endswith('.xml') and n not in ('word/document.xml','word/settings.xml'):
        try:
            r=etree.fromstring(files[n])
        except: continue
        if r.xpath('.//w:ins|.//w:del',namespaces=ns):
            files[n]=etree.tostring(accept(r),xml_declaration=True,encoding='UTF-8',standalone='yes')
with ZipFile(out,'w',ZIP_DEFLATED) as zout:
    for n,b in files.items(): zout.writestr(n,b)
print(out)
